// regra — um gatilho por rodada. Agenda e Manual rodam de verdade (seco=false); o W11 ("Verificar agora")
// chama com {seco, execucao_id?}: seco NÃO escreve em licitacoes (db/020_registrar_vista.sql:12-21) e
// execucao_id é a linha de execucoes_workflow que o W11 já abriu e devolveu ao site (plano §5 W11).
const rodou = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const e = $input.first().json || {};
const gatilho = rodou('Chamado por outro fluxo') ? 'subfluxo' : rodou('Agenda 06:00 seg-sex') ? 'agenda' : 'manual';
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
return [{ json: {
  hoje: $now.setZone('America/Sao_Paulo').toISODate(),
  inicio: $now.toUTC().toISO(),
  gatilho,
  // Sem `seco` explícito, o chamado por outro fluxo é seco: listar nunca pode gravar por descuido.
  seco: gatilho === 'subfluxo' ? e.seco !== false : false,
  execucao_id: gatilho === 'subfluxo' ? num(e.execucao_id) : null,
  // Teto de chamadas ao Jev por rodada (sinal pago, T25). A rodada Manual é a de teste: 100.
  jev_teto: gatilho === 'manual' ? 100 : 300,
  pncp_base: 'https://pncp.gov.br/api/search/',
  tam_pagina: 50,
  paginas_abertas: 2,
} }];

// regra — ADR-015 NA CONSULTA (Fopa-v2/11-Produto-v3/Recorte de 2026 e escopo na v3.md §2): duas consultas por termo.
//   recorte: anos=<ano_minimo>|...|<ano atual> + status=todos — o ano inteiro, aberto ou não (o encerrado calibra preço);
//   abertas: status=recebendo_proposta, sem ano — o credenciamento registrado em 2025 com janela aberta
//            (RN-24: o ano do controle é o da compra, não o da sessão).
// Sempre tipos_documento=edital, ordenacao=-data, tam_pagina=50 (scripts/fopa/pncp.py:144-148).
const p = $('Parâmetros da rodada').first().json;
const execucaoId = $('Abrir execução').first().json.execucao_id;
const t = $input.first().json;
const termos = Array.isArray(t.termos) ? t.termos : [];
if (!termos.length) throw new Error('W01: nenhum termo ativo em `termos` — sem termo, a coleta seria cega sem aviso');
const minimo = Number(t.ano_minimo);
const atual = Math.max(Number(t.ano_atual), minimo);
const anos = [];
for (let a = minimo; a <= atual; a++) anos.push(a);
const qs = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
const url = (termo, filtros, pagina) => p.pncp_base + '?' + qs({ q: termo, tipos_documento: 'edital', ordenacao: '-data',
                                                                 pagina, tam_pagina: p.tam_pagina, ...filtros });
const itens = [];
for (const x of termos) {
  const consultas = [
    { modo: 'recorte', rotulo: `${x.termo} [${minimo}]`, limite: Math.max(1, Number(x.paginas) || 1),
      filtros: { status: 'todos', anos: anos.join('|') } },
    { modo: 'abertas', rotulo: `${x.termo} [abertas]`, limite: p.paginas_abertas,
      filtros: { status: 'recebendo_proposta' } },
  ];
  for (const c of consultas) {
    itens.push({ json: { execucao_id: execucaoId, fase: 1, rotulo: c.rotulo, termo: x.termo, modo: c.modo, pagina: 1,
                         limite: c.limite, total: null, filtros: c.filtros, url: url(x.termo, c.filtros, 1) } });
  }
}
return itens;

// regra — depois de uma página curta ou que falhou não se pede a seguinte (scripts/fopa/pncp.py:147-160):
// ela fica "não lida" — sem linha em buscas_paginas, e a cobertura da consulta mostra o que faltou.
return { json: { ...$json, pulada: true, n_itens: 0 } };

// regra — 429 e 5xx esperam 30 s e tentam UMA vez mais: o 429 do PNCP não manda Retry-After e às vezes vem em HTML
// (scripts/fopa/pncp.py:62-100). Conexão derrubada (reset, socket hang up, DNS, timeout) tenta até 5 vezes com espera
// crescente (pncp.py:_get também insiste em toda exceção). Medido em 24/09/2026 às 04h: o PNCP resetava ~40% das
// conexões na hora, com curl e com o n8n, e uma 2ª tentativa só não bastava (6 de 23 páginas caíram duas vezes).
const ctx = $('Ler esta página?').item.json;
const tentativa = 1;
const r = $json || {};
let status = typeof r.statusCode === 'number' ? r.statusCode : null;
let rede = null;
if (r.error !== undefined && status === null) {
  const e = r.error || {};
  rede = String(e.message || e.code || e.description || JSON.stringify(e)).slice(0, 300);
  if (/^\d{3}$/.test(String(e.httpCode || ''))) status = Number(e.httpCode);
}
let corpo = r.body;
if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (x) { /* o 429 do PNCP vem em HTML */ } }
const itens = corpo && typeof corpo === 'object' && Array.isArray(corpo.items) ? corpo.items : null;
let motivo = null;
let tipo = null;
if (rede) { motivo = 'rede: ' + rede; tipo = 'rede'; }
else if (status === 429 || (status !== null && status >= 500)) { motivo = 'HTTP ' + status; tipo = 'limite'; }
else if (status !== 200) { motivo = 'HTTP ' + status; tipo = 'http'; }
else if (!itens) { motivo = 'HTTP 200 sem items'; tipo = 'rede'; }
const falhou = motivo !== null;
const historico = [...(ctx.historico || []), ...(falhou ? [tentativa + 'ª: ' + motivo] : [])];
// 429/5xx: UMA espera de 30 s e nova tentativa. Conexão derrubada: até 5 tentativas, esperando 1, 2, 4 e 8 s (a queda é instantânea e sem padrão de tempo).
const repetir = falhou && ((tipo === 'limite' && !ctx.esperou_limite) || (tipo === 'rede' && tentativa < 5));
return { json: {
  ...ctx,
  tentativa,
  status,
  falhou,
  motivo: falhou ? historico.join(' | ') : null,
  historico,
  repetir,
  esperou_limite: ctx.esperou_limite === true || (repetir && tipo === 'limite'),
  espera_s: tipo === 'limite' ? 30 : Math.min(8, 2 ** (tentativa - 1)),
  total: itens ? (Number(corpo.total) || 0) : (ctx.total ?? null),
  itens,
} };

// regra — mesma avaliação da 1ª; esgotadas as tentativas, a página fica `falhou=true` com o histórico de motivos e a
// consulta para aqui (scripts/fopa/pncp.py:147-154 — o parcial já gravado é aproveitado).
const ctx = $('Esperar e tentar de novo').item.json;
const tentativa = (Number(ctx.tentativa) || 1) + 1;
const r = $json || {};
let status = typeof r.statusCode === 'number' ? r.statusCode : null;
let rede = null;
if (r.error !== undefined && status === null) {
  const e = r.error || {};
  rede = String(e.message || e.code || e.description || JSON.stringify(e)).slice(0, 300);
  if (/^\d{3}$/.test(String(e.httpCode || ''))) status = Number(e.httpCode);
}
let corpo = r.body;
if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (x) { /* o 429 do PNCP vem em HTML */ } }
const itens = corpo && typeof corpo === 'object' && Array.isArray(corpo.items) ? corpo.items : null;
let motivo = null;
let tipo = null;
if (rede) { motivo = 'rede: ' + rede; tipo = 'rede'; }
else if (status === 429 || (status !== null && status >= 500)) { motivo = 'HTTP ' + status; tipo = 'limite'; }
else if (status !== 200) { motivo = 'HTTP ' + status; tipo = 'http'; }
else if (!itens) { motivo = 'HTTP 200 sem items'; tipo = 'rede'; }
const falhou = motivo !== null;
const historico = [...(ctx.historico || []), ...(falhou ? [tentativa + 'ª: ' + motivo] : [])];
// 429/5xx: UMA espera de 30 s e nova tentativa. Conexão derrubada: até 5 tentativas, esperando 1, 2, 4 e 8 s (a queda é instantânea e sem padrão de tempo).
const repetir = falhou && ((tipo === 'limite' && !ctx.esperou_limite) || (tipo === 'rede' && tentativa < 5));
return { json: {
  ...ctx,
  tentativa,
  status,
  falhou,
  motivo: falhou ? historico.join(' | ') : null,
  historico,
  repetir,
  esperou_limite: ctx.esperou_limite === true || (repetir && tipo === 'limite'),
  espera_s: tipo === 'limite' ? 30 : Math.min(8, 2 ** (tentativa - 1)),
  total: itens ? (Number(corpo.total) || 0) : (ctx.total ?? null),
  itens,
} };

// regra — o total declarado diz quantas páginas existem (scripts/fopa/pncp.py:118-160; ADR-007): pede-se até
// ceil(total/50), nunca além de termos.paginas (recorte) ou 2 (abertas). Página 1 curta ou que falhou encerra a consulta.
const p = $('Parâmetros da rodada').first().json;
const primeiras = $input.all().map(i => i.json);
const qs = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
const url = (termo, filtros, pagina) => p.pncp_base + '?' + qs({ q: termo, tipos_documento: 'edital', ordenacao: '-data',
                                                                 pagina, tam_pagina: p.tam_pagina, ...filtros });
const consultas = primeiras.map(c => ({ rotulo: c.rotulo, termo: c.termo, modo: c.modo, limite: c.limite,
                                        total: c.total ?? null }));
const saida = [];
for (const c of primeiras) {
  if (c.falhou || Number(c.n_itens) < p.tam_pagina) continue;
  const n = Math.min(Number(c.limite), Math.ceil(Number(c.total || 0) / p.tam_pagina));
  for (let pg = 2; pg <= n; pg++) {
    saida.push({ execucao_id: c.execucao_id, fase: 2, rotulo: c.rotulo, termo: c.termo, modo: c.modo, pagina: pg,
                 limite: c.limite, total: c.total, filtros: c.filtros, url: url(c.termo, c.filtros, pg) });
  }
}
// `consultas` (o total declarado de cada uma) vai no 1º item: o Consolidar lê daqui.
if (!saida.length) return [{ json: { nenhuma: true, consultas } }];
saida[0].consultas = consultas;
return saida.map(json => ({ json }));

// regra — do api/search do PNCP para as colunas de licitacoes (db/020_registrar_vista.sql:125-146): controle =
// numero_controle_pncp (RN-24), objeto = description[:1200], fim_prazo = data_fim_vigencia (scripts/20_monitor.py:97-105),
// atualizado_pncp = data_atualizacao_pncp[:19] (20_monitor.py:121-128). O texto que a REGRA de escopo julga é o do
// monitor: description + objeto + objetoCompra + title (scripts/20_monitor.py:90-94).
const RE = /^(\d{14})-(\d+)-(\d+)\/(\d{4})$/;
const txt = (v) => (v === null || v === undefined || v === false || v === 0) ? '' : String(v);
const saida = [];
for (const { json: r } of $input.all()) {
  const it = r.item || {};
  const controle = String(r.controle || '').trim();
  const m = RE.exec(controle);
  if (!m) continue;   // fora do formato, a CHECK de licitacoes recusaria: conta como descarte no resumo
  const cnpj = /^\d{14}$/.test(String(it.orgao_cnpj || '')) ? String(it.orgao_cnpj) : m[1];
  const ano = Number(it.ano) || Number(m[4]);
  const seq = Number(it.numero_sequencial) || Number(m[3]);
  saida.push({ json: {
    controle,
    texto_escopo: ['description', 'objeto', 'objetoCompra', 'title'].map(c => txt(it[c])).join(' '),
    payload: {
      controle, ano, seq,
      orgao: it.orgao_nome ?? null,
      uf: it.uf ?? null,
      municipio: it.municipio_nome ?? null,
      modalidade: it.modalidade_licitacao_nome ?? null,
      objeto: txt(it.description).slice(0, 1200) || null,
      situacao: it.situacao_nome ?? null,
      publicado_em: it.data_publicacao_pncp ?? null,
      fim_prazo: it.data_fim_vigencia ?? null,
      atualizado_pncp: it.data_atualizacao_pncp ? String(it.data_atualizacao_pncp).slice(0, 19) : null,
      link: `https://pncp.gov.br/app/editais/${cnpj}/${ano}/${seq}`,
    },
  } });
}
return saida;

// regra — ADR-003: a REGRA decide o escopo, antes de qualquer IA (scripts/fopa/escopo.py via POST /escopo,
// api/worker.py:208-221). escopo_versao vai junto: quando a regra muda, db/019 reavalia pelo que foi gravado.
const r = $input.first().json;
const norm = $('Normalizar').all();
const res = Array.isArray(r.resultados) ? r.resultados : null;
if (!res || res.length !== norm.length) {
  throw new Error(`W01: /escopo devolveu ${res ? res.length : 'nada'} vereditos para ${norm.length} objetos`);
}
return norm.map(({ json: n }, i) => ({ json: {
  controle: n.controle,
  dentro: res[i].dentro === true,
  texto_escopo: n.texto_escopo,
  payload: { ...n.payload, escopo_dentro: res[i].dentro === true, escopo_motivo: res[i].motivo ?? null,
             escopo_versao: r.escopo_versao ?? null },
} }));

// regra — o Jev é SINAL, nunca decide (T25; api/jev.py:1-14; Fopa-v2/11-Produto-v3/Jev na v3.md): score só das
// linhas que ESTA rodada inseriu (nova e fora de escopo), nunca no seco; teto de chamadas por rodada, e o que passou
// do teto fica registrado no resumo (contadores.jev.fora_do_teto).
const p = $('Parâmetros da rodada').first().json;
if (p.seco) return [];
const regs = $input.all().map(i => i.json);
const aplic = $('Aplicar a regra').all().map(i => i.json);
const alvo = [];
regs.forEach((r, i) => {
  if (r.acao !== 'inserir_nova' && r.acao !== 'inserir_fora_escopo') return;
  if (!aplic[i] || aplic[i].controle !== r.controle) throw new Error('W01: registro e regra fora de ordem em ' + r.controle);
  alvo.push({ controle: r.controle, objeto: aplic[i].texto_escopo, nova: r.acao === 'inserir_nova' });
});
// As novas primeiro: são as que entram na fila paga.
alvo.sort((a, b) => Number(b.nova) - Number(a.nova));
const vez = alvo.slice(0, p.jev_teto);
return [{ json: { itens: vez.map(({ controle, objeto }) => ({ controle, objeto })),
                  fora_do_teto: alvo.slice(p.jev_teto).map(a => a.controle), teto: p.jev_teto } }];

// regra — o worker MONTA a pergunta (o critério MEDIDO, api/jev.py:36 e 52-56; hoje v3) e diz o que a regra decidiu ao lado:
// é contra ela que o Jev discorda. O n8n só faz a chamada, com a credencial `jev` (segredo só em Credential).
const d = $input.first().json;
if (!Array.isArray(d.requisicoes)) return [];
return d.requisicoes.map(r => ({ json: { url: d.url, controle: r.controle, regra_dentro: r.regra_dentro === true, body: r.body } }));

// regra — "nada a fazer" ≠ "não consegui olhar" (scripts/20_monitor.py:408-435): a rodada fecha com contadores,
// cobertura e `cego`. Este ramo roda DEPOIS do de cima inteiro (executionOrder v1: ramo de cima primeiro, até o fim),
// então lê o que o registro e o Jev fizeram — e também fecha quando o de cima parou sem item (nada lido).
const p = $('Parâmetros da rodada').first().json;
const cons = $input.first().json;
const rodou = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const todos = (n) => rodou(n) ? $(n).all().map(i => i.json) : [];
const regs = todos('Registrar vista');
const por_acao = {};
for (const r of regs) por_acao[r.acao] = (por_acao[r.acao] || 0) + 1;
const lista = (a) => regs.filter(r => r.acao === a).map(r => r.controle);
const escolha = todos('Escolher para o Jev')[0] || null;
const reqs = todos('Uma requisição por item');
const respJev = todos('Jev (TypeSafe)');
const sinais = todos('Jev: interpretar (worker)').map((s, i) => ({ ...s, controle: reqs[i] ? reqs[i].controle : null }));
const comP = sinais.filter(s => typeof s.p_filtro_ok === 'number');
const corpos = todos('Jev: montar corpos (worker)')[0] || null;
const jev = {
  teto: p.jev_teto,
  chamadas: respJev.length,
  com_resposta: comP.length,
  falhas: respJev.filter(j => j.error).length + sinais.filter(s => s.error).length,
  p_filtro_ok_medio: comP.length ? Math.round(10000 * comP.reduce((a, s) => a + s.p_filtro_ok, 0) / comP.length) / 10000 : null,
  candidatas: sinais.filter(s => s.candidata).map(s => s.controle),
  discordancias: sinais.filter(s => s.discorda).length,
  usd: Math.round(1e8 * sinais.reduce((a, s) => a + (Number(s.usd) || 0), 0)) / 1e8,
  fora_do_teto: escolha ? escolha.fora_do_teto : [],
  erro: corpos && corpos.error ? String(corpos.error.message || corpos.error) : null,
  motivo: p.seco ? 'seco: o Jev não é chamado' : null,
};
const unicos = todos('Itens únicos da rodada').length;
const novas = lista('inserir_nova');
const retificadas = lista('retificar');
// regra — o "Verificar agora" do site é SECO (W11 → W01 seco): as novas não vão para licitacoes, então a tela
// só consegue listá-las se a rodada as guardar. Até 50, com o que o operador precisa para decidir se olha;
// a contagem `novas` continua sendo o total.
const payloadDe = {};
for (const x of todos('Normalizar')) payloadDe[x.controle] = x.payload || {};
const novas_lista = novas.slice(0, 50).map((ctrl) => {
  const y = payloadDe[ctrl] || {};
  return { controle: ctrl, municipio: y.municipio ?? null, uf: y.uf ?? null, modalidade: y.modalidade ?? null,
           objeto: y.objeto ? String(y.objeto).slice(0, 200) : null, fim_prazo: y.fim_prazo ?? null,
           link: y.link ?? null };
});
const contadores = {
  vistas: regs.length,
  novas: novas.length,
  retificadas: retificadas.length,
  fora_escopo: por_acao.inserir_fora_escopo || 0,
  fora_janela: por_acao.inserir_fora_janela || 0,
  fora_recorte: por_acao.ignorar || 0,
  conhecidas: por_acao.visto || 0,
  paginas_lidas: cons.paginas_lidas,
  lidos: cons.lidos,
  unicos,
  descartados: Math.max(0, unicos - regs.length),
  consultas_falhas: cons.consultas_falhas,
  jev_chamadas: jev.chamadas,
  seco: p.seco,
  por_acao,
  novas_lista,
  jev,
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// regra — o 1º dos DOIS e-mails do produto: UM por licitação que esta rodada inseriu como 'inserir_nova' (dentro do escopo e da
// janela, db/020) — nunca na rodada seca, que não grava. Vai para os admins (para = NULL, o W50 resolve). A coleta
// CEGA não manda mais e-mail: fica em execucoes_workflow.cego e na página /saude.
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const quando = (iso) => {
  if (!iso) return 'sem data';
  const d = new Date(iso);
  return isNaN(d) ? String(iso) : d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit',
    month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const avisos = p.seco ? [] : novas.map((ctrl) => {
  const y = payloadDe[ctrl] || {};
  const onde = `${y.municipio || y.orgao || ctrl}/${y.uf || '—'}`;
  return {
    controle: ctrl,
    assunto: `[FOPA] Licitação nova de folha: ${onde}${y.modalidade ? ' · ' + y.modalidade : ''}`,
    corpo_html: `<p><b>${esc(onde)}</b>${y.orgao ? ' — ' + esc(y.orgao) : ''}</p>`
      + `<p>${esc(y.modalidade || 'modalidade não informada')} · prazo: <b>${esc(quando(y.fim_prazo))}</b></p>`
      + (y.objeto ? `<p>${esc(String(y.objeto).slice(0, 600))}</p>` : '')
      + `<p><a href="${esc(site)}/licitacao/${esc(ctrl.replace('/', '-'))}">Abrir no site</a>`
      + (y.link ? ` · <a href="${esc(y.link)}">PNCP</a>` : '') + `</p>`
      + `<p style="color:#666">controle ${esc(ctrl)} · encontrada pelo W01 em ${esc(p.hoje)}</p>`,
  };
});
return [{ json: {
  execucao_id: $('Abrir execução').first().json.execucao_id,
  contadores, cego: cons.cego === true, avisos, inicio: p.inicio,
  saida: { vistas: regs.length, por_acao, novas, retificadas, cego: cons.cego === true, seco: p.seco,
           jev: { chamadas: jev.chamadas, com_resposta: jev.com_resposta, p_filtro_ok_medio: jev.p_filtro_ok_medio,
                  candidatas: jev.candidatas, usd: jev.usd, fora_do_teto: jev.fora_do_teto.length },
           consultas: cons.consultas },
} }];

// regra — o que o W11 e quem chamar recebem: {vistas, por_acao, novas, retificadas, cego, jev} (plano §5 W01, passo 20).
const r = $('Resumo da rodada').first().json;
const f = $input.first().json;
return [{ json: { execucao_id: f.execucao_id, duracao_s: f.duracao_s, email_cego_id: f.email_id ?? null, emails_novas: f.emails_novas ?? 0, ...r.saida } }];
